  const icon=(name)=>`<svg viewBox="0 0 22 22" aria-hidden="true"><path d="${paths[name]||paths.folder}"/></svg>`;
  let S,loadError=false; try{const raw=null;if(raw){S=JSON.parse(raw);const migrated=migrateLegacy(S);if(!validateWorkspace(S))throw new Error('schema');if(migrated)void 0;}}catch{loadError=true;S=null;} if(!S)S=clone(MISSION_SEED); if(!Object.hasOwn(S,'actorId'))S.actorId='P03';S.lang=S.lang||'zh';
  let view=new URLSearchParams(location.search).get('view')||'home';
