  const context=q=>{const {events,comments,queue,approval,...fields}=q;return {task:clone(fields),evidence:clone(taskEvidence(q)),device:clone(S.devices.find(d=>d.id===q.device)||null),tool:clone(S.tools.find(d=>d.id===q.tool)||null),binding:binding(q),decision:q.approval?{actor:q.approval.actor,actorId:q.approval.actorId,time:q.approval.time,text:q.approval.text,decision:q.approval.decision}:null,scope:'record-follow-up-advice-only'};};
  if(!S.initialized){const first=t();if(first)first.queue=binding(first);first?.events.forEach(e=>{e.source='preset-reference-record';e.context={taskId:first.id,version:1,reference:true};});S.initialized=true;}
  const persist=()=>{if(loadError){toast('已有存储无法读取，请先恢复工作区');return false;}try{void 0;return true;}catch{toast('保存失败，请保留当前输入并重试');return false;}};
  const commit=change=>{const before=clone(S);change();if(persist())return true;S=before;return false;};
  const toast=s=>{$('#toast').textContent=s;applyLanguage($('#toast'));$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600);};
  const actor=()=>S.people.find(p=>p.id===S.actorId);
  const canEdit=(q=null)=>!loadError&&actor()?.enabled!==false&&['admin','operator'].includes(actor()?.role)&&(actor()?.role==='admin'||!q||q.owner===S.actorId)&&q?.status!=='已归档';
  const canAdmin=()=>!loadError&&actor()?.enabled!==false&&actor()?.role==='admin';
  const canReview=q=>!loadError&&actor()?.enabled!==false&&['admin','reviewer'].includes(actor()?.role)&&(actor()?.role==='admin'||q?.reviewer===S.actorId)&&q?.status!=='已归档';
  const validApproval=q=>q.prepared&&q.queue===binding(q)&&q.approval?.binding===binding(q);
  const event=(q,name,detail,type='task')=>q.events.push({id:crypto.randomUUID(),time:new Date().toISOString(),actor:person(S.actorId),actorId:S.actorId,name,detail,type,source:'local-user-action',context:context(q)});
  const invalidate=(q,reason)=>{if(q.queue||q.approval)event(q,'关联复核失效',reason,'review');q.queue=null;q.approval=null;if(q.status!=='已归档')q.status=q.prepared?'待送审':'待准备';};
  const href=(v,id=S.selected)=>`mission.html?view=${v}&task=${encodeURIComponent(id||'')}`;
  const taskParam=new URLSearchParams(location.search).get('task');if(taskParam&&S.tasks.some(x=>x.id===taskParam))S.selected=taskParam;
  const go=(v,id)=>{if(id&&id!==S.selected)resetCanvas();if(id)S.selected=id;persist();if($('#dialog').open)close();view=v;history.pushState({},'',href(v));query='';selection.clear();render();window.scrollTo(0,0);};
  const badge=status=>{const c={'待复核':'blue','待准备':'amber','待送审':'blue','待补充':'amber','已归档':'gray','草稿':'gray','维护中':'amber','待检查':'amber','已登记':'gray'}[status]||'gray';return `<span class="status ${c}">${esc(status)}</span>`;};
  const btn=(label,action,primary=false,ico='',disabled=false,extra='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${disabled?'disabled':''} ${extra}>${ico?icon(ico):''}${esc(label)}</button>`;
  const roleLabel=()=>({admin:'工作区管理员',operator:'研发操作员',reviewer:'资料复核员',viewer:'只读访客'})[actor()?.role||S.role];
  const nav=(v,label,ico)=>`<a class="nav-link ${view===v||(v==='tasks'&&['prepare','record'].includes(view))?'active':''}" href="${href(v)}" data-view="${v}">${icon(ico)}${label}${v==='review'&&S.tasks.some(x=>x.status==='待复核')?`<span class="counter">${S.tasks.filter(x=>x.status==='待复核').length}</span>`:''}</a>`;
  const shell=content=>`<aside class="nav-shell"><a class="brand" href="${href('home')}" data-view="home">MISSION<span class="os">OS</span></a><button class="workspace-select" data-action="workspace">${icon('folder')}<span><span data-user-content>${esc(S.workspace)}</span><small>本地资料</small></span>${icon('down')}</button><nav aria-label="全局导航"><div class="nav-group"><div class="nav-label">工作</div>${nav('home','工作台','home')}${nav('tasks','任务','tasks')}${nav('observe','作业','observe')}${nav('review','复核','review')}</div><div class="nav-group secondary"><div class="nav-label">资源</div>${nav('devices','设备','devices')}${nav('tools','工具','tools')}${nav('evidence','证据资料','evidence')}</div><div class="nav-group secondary"><div class="nav-label">组织</div>${nav('people','成员与角色','people')}${nav('settings','设置','settings')}</div></nav><div class="nav-bottom"><button class="nav-link" data-action="about">${icon('help')}帮助与关于</button><div class="meta">MISSION OS · 本地工作区</div></div></aside><div class="app-main"><header class="globalbar"><label class="global-search">${icon('search')}<input id="global-search" aria-label="全局搜索" placeholder="搜索任务、设备、资料"><kbd>⌘ K</kbd></label><div class="global-actions">${languageSelect('language-selector')}<span class="local-tag">本地</span><button class="icon-btn" aria-label="通知" data-action="notifications">${icon('bell')}</button><button class="icon-btn" aria-label="帮助" data-action="about">${icon('help')}</button><button class="avatar-btn" aria-label="当前角色" data-action="profile">${icon('people')}</button></div></header>${content}</div>`;
  const header=(title,actions='',crumb='',user=false)=>`<div class="page-title"><div>${crumb?`<div class="breadcrumb" ${user?'data-user-content':''}>${esc(crumb)}</div>`:''}<div class="title-line"><h1 ${user?'data-user-content':''}>${esc(title)}</h1></div></div><div class="page-actions">${actions}</div></div>`;
  const props=rows=>`<dl class="property-list">${rows.map(([label,value])=>`<dt>${esc(label)}</dt><dd>${value}</dd>`).join('')}</dl>`;
  const empty=(title,action='')=>`<div class="empty-state">${icon('folder')}<h3>${esc(title)}</h3>${action}</div>`;
  const taskRows=()=>{const rows=S.tasks.filter(q=>(filter==='all'||q.status===filter)&&(tab==='all'||q.status!=='已归档')&&`${q.id}${q.name}${q.project}`.toLowerCase().includes(query.toLowerCase()));return `<div class="table-wrap"><table class="task-table"><thead><tr><th style="width:36px"><input type="checkbox" aria-label="选择当前列表" data-action="select-all"></th><th>任务</th><th>状态</th><th>平台</th><th>负责人</th><th>计划日期</th></tr></thead><tbody>${rows.map(q=>`<tr class="${q.id===S.selected?'selected':''}" data-select="${q.id}"><td><input type="checkbox" aria-label="选择 ${esc(q.name)}" data-check-task="${q.id}" ${selection.has(q.id)?'checked':''}></td><td class="task-cell"><a class="task-name" data-user-content href="${href('prepare',q.id)}" data-view="prepare" data-task="${q.id}">${esc(q.name)}</a><span class="code">${esc(q.id)}</span></td><td>${badge(q.status)}</td><td class="meta">${esc(q.device||'—')}</td><td>${personUI(q.owner)}</td><td class="meta">${esc(q.date)}</td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('没有匹配的任务'):''}<div class="table-footer"><span>${rows.length} 条任务${selection.size?` · 已选 ${selection.size} 条`:''}</span><span>第 1 页 ${btn('刷新','refresh',false,'refresh',false,'class="small"')}</span></div>`;};
  const inspector=()=>{const q=t();if(!q)return '';const ev=taskEvidence(q)[0];return `<aside class="surface inspector"><div class="inspector-header"><h3>当前任务</h3><span class="code">任务详情</span></div><div class="inspector-body">${badge(q.status)}<h2 data-user-content>${esc(q.name)}</h2><div class="project" data-user-content>${esc(q.project)}</div>${props([['观察对象',userText(q.target)],['负责人',`<span class="person"><span class="person-dot">研</span>${personUI(q.owner)}</span>`],['复核人',personUI(q.reviewer)],['平台 / 工具',`${esc(q.device)} / ${esc(q.tool)}`],['计划日期',esc(q.date)]])}${ev?`<img class="inspector-image" data-imageid="${ev.id}" src="${esc(ev.src||'')}" alt="${esc(ev.name)}"><div class="image-caption"><span>${esc(ev.id)} · 人工区域</span><span>参考影像</span></div>`:''}</div><div class="inspector-actions">${btn('打开任务','open-task',true,'arrow')}${btn('查看记录','open-record')}</div></aside>`;};
  const home=()=>`<main class="view">${header('工作台',btn('新建任务','new-task',true,'plus',!canEdit()))}<div class="workbench-grid"><div><section class="surface"><div class="tabs"><button data-tab="all" class="${tab==='all'?'active':''}">全部任务</button><button data-tab="active" class="${tab==='active'?'active':''}">进行中</button></div><div class="commandbar"><label class="search-field">${icon('search')}<input id="task-search" aria-label="搜索任务" placeholder="搜索任务" value="${esc(query)}"></label><select class="filter-select" id="status-filter" aria-label="任务状态"><option value="all">全部状态</option>${['草稿','待准备','待送审','待复核','待补充','已归档'].map(x=>`<option value="${x}" ${filter===x?'selected':''}>${x}</option>`).join('')}</select><span class="spacer"></span>${selection.size?btn('归档所选','archive-selected',false,'archive',!canEdit()):btn('管理任务','go-tasks',false,'tasks')}</div><div id="task-table-area">${taskRows()}</div></section><div class="resource-strip"><section class="surface"><div class="section-head"><h2>任务设备</h2><a class="link-blue meta" href="${href('devices')}" data-view="devices">查看全部</a></div>${S.devices.map(d=>`<a class="resource-row" href="${href('devices')}" data-view="devices"><span class="resource-icon">${icon('devices')}</span><span><strong data-user-content>${esc(d.name)}</strong><div class="meta">${esc(d.id)} · ${esc(d.connection)}</div></span>${badge(d.status)}</a>`).join('')}</section><section class="surface"><div class="section-head"><h2>工具库</h2><a class="link-blue meta" href="${href('tools')}" data-view="tools">查看全部</a></div>${S.tools.map(d=>`<a class="resource-row" href="${href('tools')}" data-view="tools"><span class="resource-icon">${icon('tools')}</span><span><strong data-user-content>${esc(d.name)}</strong><div class="meta">${esc(d.id)} · ${esc(d.category)}</div></span>${badge(d.status)}</a>`).join('')}</section></div></div><div>${inspector()}<section class="surface subsection"><div class="section-head"><h2>待处理复核</h2><a class="link-blue meta" href="${href('review')}" data-view="review">打开队列</a></div>${S.tasks.filter(q=>q.status==='待复核').map(q=>`<a class="queue-mini" href="${href('review',q.id)}" data-view="review" data-task="${q.id}"><span class="queue-icon">${icon('review')}</span><span><strong data-user-content>${esc(q.suggestion||q.name)}</strong><div class="meta">${userText(q.target)} · ${personUI(q.reviewer)}</div></span><span class="arrow">${icon('arrow')}</span></a>`).join('')||empty('暂无待处理复核')}</section></div></div></main>`;
  let evidenceSelected='E-001',reviewTab='pending',draftROI=null,drawMode=false,zoom=1,settingsTab=loadError?'data':'workspace';
  const taskTabs=()=>`<div class="object-tabs">${[['prepare','计划与准备'],['observe','现场资料'],['review','复核意见'],['record','任务记录']].map(([key,label])=>`<a class="${view===key?'active':''}" href="${href(key)}" data-view="${key}">${label}</a>`).join('')}</div>`;
  const taskHead=(actions='')=>{const q=t();return header(q?.name||'任务',actions,`${q?.project||'任务'} / ${q?.id||''}`,true);};
  const choose=(name,items,value,first='请选择')=>`<select name="${name}" ${['type','role','category','status','enabled'].includes(name)?'required':''} ${name==='device'||name==='tool'?'data-resource-choice="true"':''}><option value="">${first}</option>${items.map(([id,label])=>`<option ${['owner','reviewer','device','tool'].includes(name)?'data-user-content':''} value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
  const archived=()=>t()?.status==='已归档';
  const guard=q=>{const issues=[];const dev=S.devices.find(d=>d.id===q.device),tool=S.tools.find(d=>d.id===q.tool);if(!q.goal.trim()||!q.target.trim())issues.push('任务目标缺失');if(!S.people.some(p=>p.id===q.owner&&p.enabled!==false&&['admin','operator'].includes(p.role)))issues.push('负责人未分配或已停用');if(!S.people.some(p=>p.id===q.reviewer&&p.enabled!==false&&['reviewer','admin'].includes(p.role)))issues.push('复核人未分配或无办理角色');if(!dev||dev.status==='停用'||dev.status==='维护中')issues.push('设备资源不可用');if(!tool||tool.status==='停用'||tool.status==='维护中'||!tool.identity)issues.push('工具身份不可用');if(tool&&((q.type==='observation'&&tool.category!=='观察')||(q.type==='bench'&&tool.category!=='台架交互')))issues.push('工具不适用于当前任务');if(q.checks.length!==S.checks.length||!q.checks.every(x=>x===true))issues.push('准备记录未完成');if(!['observation','bench'].includes(q.type))issues.push('请选择任务类型');return issues;};
  const prepare=()=>{const q=t();if(!q)return noTask();const dev=S.devices.find(x=>x.id===q.device),tool=S.tools.find(x=>x.id===q.tool);return `<main class="view object-view">${taskHead(btn('保存更改','save-plan',false,'save',!canEdit(q))+btn('进入作业','enter-operation',true,'arrow',!q.prepared||archived()))}${taskTabs()}<div class="detail-grid"><div><form id="plan-form" class="surface"><div class="section-head"><h2>目标与职责</h2>${badge(q.status)}</div><div class="form-body form-grid"><label class="field full"><span>任务目标</span><textarea name="goal" required>${esc(q.goal)}</textarea></label><label class="field"><span>观察对象</span><input name="target" value="${esc(q.target)}" required></label><label class="field"><span>任务类型</span>${choose('type',[['observation','观察资料'],['bench','固定台架交互']],q.type)}</label><label class="field"><span>负责人</span>${choose('owner',S.people.filter(p=>p.enabled!==false&&['admin','operator'].includes(p.role)).map(p=>[p.id,p.name]),q.owner,'未分配')}</label><label class="field"><span>复核人</span>${choose('reviewer',S.people.filter(p=>p.enabled!==false&&['reviewer','admin'].includes(p.role)).map(p=>[p.id,p.name]),q.reviewer,'未分配')}</label><label class="field"><span>计划日期</span><input type="date" name="date" value="${esc(q.date)}"></label><label class="field"><span>平台</span>${choose('device',S.devices.map(x=>[x.id,`${x.name} · ${x.id}`]),q.device)}</label><label class="field"><span>任务工具</span>${choose('tool',S.tools.map(x=>[x.id,`${x.name} · ${x.id}`]),q.tool)}</label></div></form><section class="surface block-gap"><div class="section-head"><h2>人工准备</h2><span class="meta">${q.checks.filter(Boolean).length} / ${q.checks.length}</span></div><div class="check-list">${S.checks.map((label,i)=>`<label class="check-row"><input type="checkbox" data-ready="${i}" ${q.checks[i]?'checked':''} ${!canEdit(q)?'disabled':''}><span>${esc(label)}</span><span class="check-state">${q.checks[i]?'已记录':'未记录'}</span></label>`).join('')}</div><div class="section-foot">${q.prepared?`<span class="prepared-label">${icon('check')}准备记录已保存</span>`:'<span></span>'}${btn('完成准备','complete-preparation',true,'check',!canEdit(q))}</div></section></div><aside><section class="surface"><div class="section-head"><h2>资源配置</h2><span class="code">v${q.configVersion}</span></div><div class="form-body"><div class="asset-title"><span class="resource-icon">${icon('devices')}</span><div><h3>${dev?.name?userText(dev.name):'未分配'}</h3><span class="code">${esc(q.device||'—')}</span></div></div>${props([['连接状态',dev?.connection||'未接入'],['接口配置',userText(dev?.interface||'—')],['工具',tool?.name?userText(tool.name):'未分配'],['工具身份',userText(tool?.identity||'—')],['任务版本',`v${q.version}`]])}<div class="thin-note">${icon('info')}人工准备记录</div></div></section><section class="surface block-gap"><div class="section-head"><h2>任务步骤</h2></div><div class="step-list">${[['确认目标','prepare'],['整理依据','observe'],['人员复核','review'],['补充观察','record']].map(([label,key],i)=>`<a href="${href(key)}" data-view="${key}" class="step-row"><span class="step-num">${i+1}</span><span>${label}</span>${icon('arrow')}</a>`).join('')}</div></section><div class="task-secondary">${btn('复制任务','duplicate-task',false,'tasks',!canEdit())}${btn(archived()?'恢复任务':'归档任务',archived()?'restore-task':'archive-task',false,'archive',!canAdmin())}</div></aside></div></main>`;};
  const selectedEvidence=()=>taskEvidence(t()||{evidence:[]}).find(x=>x.id===evidenceSelected)||taskEvidence(t()||{evidence:[]})[0];
  const image=(ev,roi=true,stage=false)=>{if(!ev)return empty('暂无资料',btn('导入影像','import-image',true,'upload',!canEdit(t())));const r=draftROI||ev.roi;return `<div class="image-plane ${stage?'stage-image':''}" id="image-plane" style="aspect-ratio:${ev.width}/${ev.height};--zoom:${zoom}"><img data-imageid="${ev.id}" src="${esc(ev.src||'')}" alt="${esc(ev.name)}" draggable="false">${roi&&r?`<div class="image-roi" style="left:${r.x}%;top:${r.y}%;width:${r.width}%;height:${r.height}%"><span>${t()?.target?userText(t().target):'<span>区域</span>'} · <span>人工区域</span></span></div>`:''}</div>`;};
  const thumbnails=()=>`<div class="filmstrip">${taskEvidence(t()).map(ev=>`<button class="film-item ${ev.id===selectedEvidence()?.id?'active':''}" data-evidence="${ev.id}" aria-label="${esc(ev.name)}"><img data-imageid="${ev.id}" src="${esc(ev.src||'')}" alt=""><span>${esc(ev.id)}</span></button>`).join('')}<button class="film-add" data-action="import-image" aria-label="导入影像" ${!canEdit(t())?'disabled':''}>${icon('plus')}</button></div>`;
  const observe=()=>{const q=t();if(!q)return noTask();const ev=selectedEvidence(),r=draftROI||ev?.roi;return `<main class="view object-view">${taskHead(btn('导入影像','import-image',false,'upload',!canEdit(q))+btn('提交复核','submit-review',true,'review',!canEdit(q)||!q.prepared||!ev))}${taskTabs()}<div class="operation-grid"><section class="surface canvas-panel"><div class="canvas-toolbar"><div class="segmented"><button class="${!liveMode?'active':''}" data-action="photo-mode">影像资料</button><button class="${liveMode?'active':''}" data-action="video-mode">视频源</button></div><div class="canvas-tools">${btn('人工标注','draw-region',false,'annotate',!ev||!canEdit(q))}<button class="icon-btn" aria-label="放大" data-action="zoom-in">${icon('zoom')}</button>${btn('适合画布','fit-canvas',false,'',false)}<button class="icon-btn" aria-label="查看原图" data-action="original-image">${icon('evidence')}</button></div></div><div class="photo-stage ${drawMode?'drawing':''}">${liveMode?empty('无视频源',btn('连接设置','go-settings',false,'settings')):image(ev,true,true)}</div><div class="canvas-status"><span>${ev?.name?userText(ev.name):'选择资料'}</span><span>${ev?`${ev.width} × ${ev.height}`:'—'} · ${liveMode?'未接入':'原始影像'}</span></div>${thumbnails()}</section><aside class="surface operation-inspector"><div class="tabs"><button class="active">当前对象</button></div><div class="form-body"><div class="asset-title">${icon('annotate')}<h3 data-user-content>${esc(q.target)}</h3></div>${props([['证据',esc(ev?.id||'—')],['资料来源',esc(ev?.source||'—')],['区域版本',`v${ev?.roiVersion||0}`]])}<div class="inspector-divider"></div><h3>人工区域</h3>${r?`<div class="roi-fields">${[['x','左侧'],['y','上侧'],['width','宽度'],['height','高度']].map(([key,label])=>`<label class="field"><span>${label} %</span><input type="number" min="0" max="100" data-roi-field="${key}" value="${r[key]}" ${!canEdit(q)?'disabled':''}></label>`).join('')}</div>${btn('保存区域','save-region',false,'save',!canEdit(q))}`:'<div class="empty-mini">尚未标注</div>'}<div class="inspector-divider"></div><label class="field"><span>观察笔记</span><textarea id="observation-note" rows="2">${esc(q.observationNote||'')}</textarea></label><label class="field" style="margin-top:14px"><span>后续建议</span><textarea id="advice-input" rows="2">${esc(q.suggestion)}</textarea></label><div class="section-foot" style="padding:16px 0 0;border:0">${btn('保存建议','save-advice',false,'save',!canEdit(q))}<span class="code">v${q.suggestionVersion}</span></div></div></aside></div><input id="image-input" type="file" accept="image/png,image/jpeg,image/webp" hidden></main>`;};
  let liveMode=false;
  const review=()=>{const q=t();if(!q)return noTask();const ev=selectedEvidence();const queued=q.prepared&&q.queue===binding(q)&&q.status==='待复核';const rows=S.tasks.filter(x=>reviewTab==='pending'?x.status==='待复核':x.comments?.length);return `<main class="view review-view">${header('复核工作台',btn('查看记录','open-record',false,'record'))}<div class="review-layout"><aside class="surface review-queue"><div class="tabs"><button data-reviewtab="pending" class="${reviewTab==='pending'?'active':''}">待处理</button><button data-reviewtab="processed" class="${reviewTab==='processed'?'active':''}">已处理</button></div>${rows.map(x=>`<button class="review-queue-item ${x.id===q.id?'selected':''}" data-reviewtask="${x.id}"><span class="queue-task-name" data-user-content>${esc(x.name)}</span><span class="meta" data-user-content>${esc(x.target)}</span><div>${badge(x.status)}<span class="code">${esc(x.tool)}</span></div></button>`).join('')||empty('暂无复核事项')}</aside><section class="surface review-case"><div class="review-case-head"><span class="code">${esc(q.id)}</span>${badge(validApproval(q)?'已确认':queued?'待复核':'已失效')}</div><div class="review-case-body"><h2 data-user-content>${esc(q.suggestion||q.name)}</h2><div class="review-image">${image(ev)}</div><div class="review-image-label"><span>${esc(ev?.id||'—')} · v${ev?.version||0} · 人工区域</span><button class="btn quiet small" data-action="original-image">查看原图</button></div><div class="review-facts">${props([['判断依据',ev?userText(ev.name):'暂无资料'],['信息缺口',q.observationNote?userText(q.observationNote):(q.id==='OBS-20000101-01'?'另一侧表面与接合区域不可见':'暂无意见')],['确认范围','后续观察建议']])}</div></div></section><aside class="surface decision-panel"><div class="section-head"><h2>人员意见</h2><span class="code">v${q.suggestionVersion}</span></div><div class="form-body">${props([['指定复核人',personUI(q.reviewer)],['当前角色',roleLabel()],['任务版本',`v${q.version}`],['配置版本',`v${q.configVersion}`],['证据版本',`v${ev?.version||0}`]])}<div class="inspector-divider"></div><label class="field"><span>复核意见</span><textarea id="review-comment" placeholder="填写意见" rows="4"></textarea></label><label class="consent-row"><input type="checkbox" id="review-consent" ${!queued||!canReview(q)?'disabled':''}><span>已查看当前依据</span></label>${btn('接受建议','accept-review',true,'check',true)}${btn('退回补充','return-review',false,'arrow',!queued||!canReview(q))}${!queued&&!validApproval(q)?'<div class="action-alert">当前依据需重新提交</div>':''}${!canReview(q)?'<div class="action-alert">当前角色无办理权限</div>':''}<div class="thin-note">${icon('info')}仅记录后续观察建议</div></div></aside></div></main>`;};
  const record=()=>{const q=t();if(!q)return noTask();const rows=q.events.filter(e=>recordFilter==='all'||e.type===recordFilter).slice().reverse();return `<main class="view object-view">${taskHead(btn('导出记录','export-record',true,'download'))}${taskTabs()}<div class="record-grid"><section class="surface"><div class="commandbar"><div class="segmented">${[['all','全部事件'],['task','任务事件'],['evidence','资料事件'],['review','复核事件']].map(([key,label])=>`<button class="${recordFilter===key?'active':''}" data-eventfilter="${key}">${label}</button>`).join('')}</div><span class="spacer"></span><span class="meta">${rows.length} 条事件</span></div><div class="event-list">${rows.map((e,i)=>`<article class="event-row"><span class="event-marker">${icon(e.type==='review'?'review':e.type==='evidence'?'evidence':'tasks')}</span><div><div class="event-title"><h3>${esc(e.name)}</h3><time data-time="${esc(e.time)}">${formatTime(e.time)}</time></div><p data-user-content>${esc(e.detail)}</p><div class="event-sub"><span data-user-content>${esc(e.actor)}</span><span>${e.source==='preset-reference-record'?'参考记录':'本地记录'}</span><button class="btn quiet small" data-eventid="${esc(e.id)}">查看当时依据</button></div></div></article>`).join('')||empty('暂无记录')}</div></section><aside><section class="surface"><div class="section-head"><h2>当前决定</h2>${badge(validApproval(q)?'已确认':'待补充')}</div><div class="form-body"><h2 style="font-size:18px">${validApproval(q)?'等待补充观察':'暂无有效决定'}</h2>${props([['办理人员',userText(q.approval?.actor||'—')],['确认范围','后续观察建议'],['设备动作','未产生设备命令'],['当前版本',`v${q.version}`]])}</div></section><section class="surface block-gap"><div class="section-head"><h2>关联文件</h2><span class="meta">${q.evidence.length}</span></div>${taskEvidence(q).map(ev=>`<button class="file-row" data-open-evidence="${ev.id}">${icon('evidence')}<span><strong data-user-content>${esc(ev.name)}</strong><span class="code">${esc(ev.id)} · v${ev.version}</span></span>${icon('arrow')}</button>`).join('')||empty('暂无资料')}</section><section class="surface block-gap"><div class="section-head"><h2>人员意见</h2></div>${q.comments.map(c=>`<div class="comment-item"><strong data-user-content>${esc(c.actor)}</strong><span class="meta" data-time="${esc(c.time)}">${formatTime(c.time)}</span><p data-user-content>${esc(c.text||c.decision)}</p></div>`).join('')||'<div class="empty-mini">暂无意见</div>'}</section></aside></div></main>`;};
