    if(action==='profile'){dialog('当前角色',`<label class="field"><span>本地角色视图</span><select id="actor-choice">${S.people.filter(p=>p.enabled!==false).map(p=>`<option data-user-content value="${p.id}" ${S.actorId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}<option value="" ${!S.actorId?'selected':''}>只读访客</option></select></label><p class="dialog-info" style="margin-top:14px">角色仅控制本地界面的操作入口。生产身份认证需后端接入。</p>`,btn('取消','close-dialog')+btn('应用角色','apply-role',true));return;}
