    if(!state.tasks.every(q=>['id','name','project','target','goal','type','owner','reviewer','date','device','tool','status','suggestion'].every(k=>typeof q[k]==='string')&&['observation','bench'].includes(q.type)&&['checks','events','comments','evidence'].every(k=>Array.isArray(q[k]))&&q.checks.length===state.checks.length&&q.checks.every(x=>typeof x==='boolean')&&typeof q.prepared==='boolean'&&['version','configVersion','suggestionVersion'].every(k=>Number.isInteger(q[k])&&q[k]>0)&&q.evidence.every(id=>state.evidence.some(ev=>ev.id===id&&ev.task===q.id))&&q.events.every(e=>e&&['id','time','actor','name','detail','type'].every(k=>typeof e[k]==='string')&&Number.isFinite(new Date(e.time).getTime()))&&q.comments.every(c=>c&&typeof c.actor==='string'&&typeof c.time==='string'&&typeof c.decision==='string')))return false;
